// TH15 type 0..43 synthetic aliases, copied from transcribe/th15/touhou-bullets.ecl.
// This card's etSprite calls use only source types 12 and 18.
const TH15_ARROWHEAD: int = 544; // source type 12 (MBossCard2_at)
const TH15_BIG_BALL: int = 640;  // source type 18 (MBossCard2_at2)

// TH15 v1.00b Extra midboss 2nd spell: 超特急「ドリームエクスプレス」
// Source: st07mbs.ecl.txt MBoss2 (53-93) -> MBossCard2 (244-308),
// MBossCard2_at (310-331), MBossCard2_at2 (333-355).
// Shell: TH15 validation.md -> TH18 card-format appendix (control + phase_begin).
// Frame mapping: card frame 0 = phase start; source attack begins after the 120-frame
// opening buffer. MBoss2's in-card wait is 160, then MBossCard2's 3000-frame timer.
// TIME_LIMIT = 120 + 160 + 3000 + 4 (startup margin) = 3284.
const TIME_LIMIT: int = 3284;
const OPENING_BUFFER: int = 120;

// Entry position from MBoss common (st07mbs.ecl.txt:27-30): movePos(-192,-64) then
// movePosTime(100,4,0,128) -> (0,128). MBoss2 itself sets no position.
const BOSS_X: fx = 0fx;
const BOSS_Y: fx = 128fx;

// moveLimit(0,128,280,64) from st07mbs.ecl.txt:279: x in [-140,140], y in [96,160];
// moveRand's direction-selection inner box is center +- width/4 / height/4:
// x in [-70,70], y in [112,144].
const LIMIT_LEFT: fx = -140fx;
const LIMIT_RIGHT: fx = 140fx;
const LIMIT_TOP: fx = 96fx;
const LIMIT_BOTTOM: fx = 160fx;
const INNER_LEFT: fx = -70fx;
const INNER_RIGHT: fx = 70fx;
const INNER_TOP: fx = 112fx;
const INNER_BOTTOM: fx = 144fx;

// Source MBossCard2_at etEx type 0x200000 (VELTIME): a=60, r=8.0, s=-999999 keeps
// the birth angle. The bullet starts at speed 1.0 and ramps to 8.0 over 60 frames.
xformdef AT_RAMP {
    step_speed(8fx, 60 + 65536 * EASE_LINEAR);
}

// MBossCard2_at (310-331): one of nine parallel streams.
// Source etSprite(A,12,B): shape 12, color B. etAim(A,3) + etCount(1,1) +
// etAngle(A,F0,1.0) fire along the wave-start player angle F0 (not re-aimed per shot).
// etOffsetRad(A, F0-pi/2, C): spawn at boss + C perpendicular to F0.
// etEx type 2 (ANIM) a=1: position -= 4 * birth velocity (speed 1.0).
async sub card2_at(shape: int, color: int, off: fx, ang: angle) {
    for i in 0..10 {
        var ox: fx = off * cos(ang - 90deg);
        var oy: fx = off * sin(ang - 90deg);
        var bx: fx = $self_x + ox - 4fx * cos(ang);
        var by: fx = $self_y + oy - 4fx * sin(ang);
        _ = fire(shape, color, bx, by, 1fx, ang, AT_RAMP, none);
        wait(6);
    }
}

// MBossCard2_at2 (333-355): 32-way big-ball rings, first shot immediately,
// interval B = 60 then 58..30 (then 30), i.e. wait(B) with B -= 2 while B > 30.
async sub card2_at2() {
    var b: int = 60;
    loop {
        var base: angle = aim_player(); // source etAngle base = ANGLE_PLAYER
        for i in 0..32 {
            var phi: angle = ((i * 65536) / 32) as angle;
            var a: angle = base + phi;
            // TH15 mode11: v=4*(1-(-0.1)*abs(sin(phi))). See
            // transcribe/th15/aim-modes.md; verified native SIMD sin return.
            var wave: fx = sin(phi);
            if wave < 0fx { wave = -wave; }
            var speed: fx = 4fx + 2fx * wave / 5;
            // ANIM=1 retains the -4*birth-velocity displacement; visuals omitted.
            var bx: fx = $self_x - 4fx * speed * cos(a);
            var by: fx = $self_y - 4fx * speed * sin(a);
            _ = fire(TH15_BIG_BALL, 1, bx, by, speed, a, none, none);
        }
        wait(b);
        if b > 30 {
            b = b - 2;
        }
    }
}

// moveRand(60,4,1.0) target recipe (TH16 movement.md), adapted to this card's
// moveLimit(0,128,280,64). Speed is linear from 1.0 to 0 over k=1..60; the source
// angle mode 4 does not override the speed interpolation mode.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 {
        speed = ((60 - k) as fx) / 60;
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < LIMIT_LEFT {
        nx = LIMIT_LEFT;
    }
    if nx > LIMIT_RIGHT {
        nx = LIMIT_RIGHT;
    }
    if ny < LIMIT_TOP {
        ny = LIMIT_TOP;
    }
    if ny > LIMIT_BOTTOM {
        ny = LIMIT_BOTTOM;
    }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    // Source 405b90 = signed unit random * pi; values below are unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < INNER_LEFT {
        a = r / 3;
    } else if $self_x > INNER_RIGHT {
        a = r / 3 + 32768;
        if a > 32768 {
            a = a - 65536;
        }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 {
                a = a + 32768;
            }
        } else {
            if choose != 0 {
                a = a + 32768;
            }
        }
    }
    if $self_y < INNER_TOP {
        if a < 0 {
            a = -a;
        }
    } else if $self_y > INNER_BOTTOM {
        if a < 0 {
            a = -a;
        }
        a = -a;
    }
    // Native +-pi/2 guard, epsilon 0.05 rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 {
            a = -16906;
        } else {
            a = -15862;
        }
    } else if a > 15862 && a < 16906 {
        if a < 16384 {
            a = 15862;
        } else {
            a = 16906;
        }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

async sub card2_main() {
    // MBoss2 entry (st07mbs.ecl.txt:53-93). lifeSet(2200) is the spawn hp;
    // setInvuln(180) is covered by the training shell's permanent invulnerability.
    set_invuln(65535);
    // MBoss common (st07mbs.ecl.txt:24-25): setHurtbox(48,48) -> 24, setHitbox(40,40) -> 20.
    set_hitbox(20fx);
    set_hurtbox(24fx);
    // Omitted by the shared TH15 policy: setChapter, unknown569, BossItemPhase/drops,
    // etCancel/etClear, killAllAsync/enmKillAll (no prior tasks/enemies in this card),
    // spellEnd, funcSet(0), laserCancel, playSound, moveVel/moveVelTime/movePosTime
    // zeroing (boss starts stationary), anm*.
    wait(160); // MBoss2's only in-card wait before MBossCard2

    // MBossCard2 (st07mbs.ecl.txt:244-308). timerReset + setInterrupt(0,0,3000,"MBoss3")
    // + spellEx(107,3000,...) are represented by the shell phase timer; MBoss3 is the
    // next card and is not imported.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT); // movePosTime(60,4,0,144)
    wait(60);
    wait(30); // source local t=64 -> t=94 (the +90 label after wait(60))
    spawn card2_at2();

    loop {
        var ang: angle = aim_player(); // %F0 = %ANGLE_PLAYER at MBossCard2_1040
        spawn card2_at(TH15_ARROWHEAD, 10, 0fx, ang);
        wait(2);
        spawn card2_at(TH15_ARROWHEAD, 11, 16fx, ang);
        spawn card2_at(TH15_ARROWHEAD, 8, -16fx, ang);
        wait(2);
        spawn card2_at(TH15_ARROWHEAD, 13, 32fx, ang);
        spawn card2_at(TH15_ARROWHEAD, 6, -32fx, ang);
        wait(2);
        spawn card2_at(TH15_ARROWHEAD, 14, 48fx, ang);
        spawn card2_at(TH15_ARROWHEAD, 4, -48fx, ang);
        wait(2);
        spawn card2_at(TH15_ARROWHEAD, 2, 64fx, ang);
        spawn card2_at(TH15_ARROWHEAD, 3, -64fx, ang);
        wait(60);
        card_move_rand(); // moveRand(60,4,1.0)
        card_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(BOSS_X, BOSS_Y, 2200, 0, 0, 0, card2_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop {
        wait(1);
    }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop {
        wait(600);
    }
}
